# Generated by scripts/install/generate.py. Edit the template and copy.json.
# Permanent installer for the complete SafeRM desktop distribution. PowerShell 5.1+.
& {
$ErrorActionPreference = 'Stop'
# Avoid PowerShell 5.1's slow progress rendering while downloading binary packages.
$ProgressPreference = 'SilentlyContinue'
$messages = @{
    unsupported = 'SafeRM supports Windows on AMD64 and ARM64.'
    invalid_version = 'SAFERM_VERSION must be a version such as 1.2.3 or v1.2.3.'
    invalid_directory = 'SAFERM_INSTALL_DIR must be an absolute local directory path without quotes or newlines.'
    checksum_failed = 'The package checksum did not match. Nothing was installed.'
    install_failed = 'The SafeRM installer failed with exit code {0}. Close SafeRM before retrying.'
    missing_executable = 'The installer did not create {0}.'
    cli_failed = 'The installed SafeRM CLI could not run.'
    installing = 'Installing SafeRM {0} for Windows {1}...'
    installed = 'SafeRM {0} is installed. Run saferm help, or open SafeRM from the Start menu.'
    shadowed_path = 'This terminal finds another saferm at {0}. The installed CLI is {1}.'
}

if ($env:OS -ne 'Windows_NT') { throw $messages.unsupported }
[Net.ServicePointManager]::SecurityProtocol = [Net.ServicePointManager]::SecurityProtocol -bor [Net.SecurityProtocolType]::Tls12
$processor = Get-CimInstance Win32_Processor | Select-Object -First 1
switch ([int]$processor.Architecture) {
    9 { $architecture = 'amd64' }
    12 { $architecture = 'arm64' }
    default { throw $messages.unsupported }
}
$releasesUrl = 'https://github.com/shdeen/saferm/releases'
$latestUrl = 'https://api.github.com/repos/shdeen/saferm/releases/latest'
$version = $env:SAFERM_VERSION
if (-not $version) { $version = (Invoke-RestMethod -Uri $latestUrl).tag_name }
$version = $version -creplace '^v', ''
if ($version -cnotmatch '\A(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\z') { throw $messages.invalid_version }
$installDirectory = $env:SAFERM_INSTALL_DIR
if (-not $installDirectory) {
    $registryPath = 'HKCU:\Software\SafeRM'
    if (Test-Path -LiteralPath $registryPath) {
        $installDirectory = (Get-ItemProperty -LiteralPath $registryPath).InstallDirectory
    }
    if (-not $installDirectory) { $installDirectory = Join-Path $env:LOCALAPPDATA 'Programs\SafeRM' }
}
if ($installDirectory -notmatch '^[A-Za-z]:[\\/]' -or $installDirectory -match '["\r\n]') { throw $messages.invalid_directory }
$installDirectory = [IO.Path]::GetFullPath($installDirectory).TrimEnd('\')
$downloadDirectory = Join-Path ([IO.Path]::GetTempPath()) ('saferm-install-' + [Guid]::NewGuid().ToString('N'))
New-Item -ItemType Directory -Path $downloadDirectory | Out-Null
try {
    $packageName = "saferm_${version}_windows_${architecture}.exe"
    $packagePath = Join-Path $downloadDirectory $packageName
    $checksumPath = Join-Path $downloadDirectory 'checksums.txt'
    Invoke-WebRequest -UseBasicParsing -Uri "$releasesUrl/download/v$version/$packageName" -OutFile $packagePath
    Invoke-WebRequest -UseBasicParsing -Uri "$releasesUrl/download/v$version/saferm_${version}_checksums.txt" -OutFile $checksumPath
    $checksumRecords = @(Get-Content -LiteralPath $checksumPath | Where-Object { $_ -match ('\A[0-9a-fA-F]{64}  ' + [regex]::Escape($packageName) + '\z') })
    if ($checksumRecords.Count -ne 1 -or (Get-FileHash -Algorithm SHA256 -LiteralPath $packagePath).Hash -ne $checksumRecords[0].Substring(0, 64)) {
        throw $messages.checksum_failed
    }
    Write-Host ($messages.installing -f $version, $architecture)
    # NSIS requires /D last and unquoted, including when its path contains spaces.
    $installerProcess = Start-Process -FilePath $packagePath -ArgumentList "/S /D=$installDirectory" -Wait -PassThru
    if ($installerProcess.ExitCode -ne 0) { throw ($messages.install_failed -f $installerProcess.ExitCode) }
    foreach ($executableName in @('saferm.exe', 'saferm-app.exe', 'saferm-notify.exe')) {
        $executablePath = Join-Path $installDirectory $executableName
        if (-not (Test-Path -LiteralPath $executablePath -PathType Leaf)) { throw ($messages.missing_executable -f $executablePath) }
    }
    $cliPath = Join-Path $installDirectory 'saferm.exe'
    & $cliPath help | Out-Null
    if ($LASTEXITCODE -ne 0) { throw $messages.cli_failed }
    # The native installer updates the user's PATH; also update this terminal immediately.
    if ($env:Path.Split(';') -notcontains $installDirectory) { $env:Path = $env:Path.TrimEnd(';') + ';' + $installDirectory }
    Write-Host ($messages.installed -f $version)
    $resolvedCli = (Get-Command saferm -CommandType Application).Source
    if ($resolvedCli -ne $cliPath) { Write-Warning ($messages.shadowed_path -f $resolvedCli, $cliPath) }
} finally {
    Remove-Item -LiteralPath $downloadDirectory -Recurse -Force
}
}
